#!/usr/bin/env python3
# record_and_mix.py — miniaudio mic capture + combat overlay at 0 dB, normalized loud. battle_0.wav BAKED IN.
import argparse,sys,wave,io,gzip,base64
import numpy as np
import miniaudio
SR=16000
BED_GZ_B64=""

def _resample(x, src, dst):
    if src==dst or len(x)==0: return x.astype(np.float32)
    t=np.linspace(0,len(x),int(len(x)*dst/src),endpoint=False)
    return np.interp(t,np.arange(len(x)),x).astype(np.float32)
def _norm(x, peak):
    if len(x)==0: return x
    ref=float(np.percentile(np.abs(x),99.5))          # robust to stray clicks
    if ref<=0: ref=float(np.max(np.abs(x)))
    return np.clip(x*(peak/ref),-1.0,1.0) if ref>0 else x
def read_wav_mono_bytes(b):
    w=wave.open(io.BytesIO(b),"rb"); sr,ch,sw,n=w.getframerate(),w.getnchannels(),w.getsampwidth(),w.getnframes(); raw=w.readframes(n)
    dt={1:np.int8,2:np.int16,4:np.int32}[sw]; x=np.frombuffer(raw,dtype=dt).astype(np.float32)/float(np.iinfo(dt).max)
    if ch>1: x=x.reshape(-1,ch).mean(axis=1)
    return _resample(x,sr,SR)
def write_wav_mono(path,x):
    pcm=(np.clip(x,-1,1)*32767).astype(np.int16)
    with wave.open(path,"wb") as w: w.setnchannels(1); w.setsampwidth(2); w.setframerate(SR); w.writeframes(pcm.tobytes())
def pick_device(want):
    caps=miniaudio.Devices().get_captures()
    if want is not None:
        return caps[want]
    real=[c for c in caps if not c["name"].lower().startswith("monitor")]
    for kw in ("m4","usb","interface"):                      # prefer an external interface
        for c in real:
            if kw in c["name"].lower(): return c
    for c in real:                                           # else any analog that is not the built-in
        n=c["name"].lower()
        if "analog" in n and "built-in" not in n: return c
    return real[0] if real else caps[0]
def list_devices():
    for i,c in enumerate(miniaudio.Devices().get_captures()): print(f"[{i}] {c['name']}")
def record(dev):
    CAP_SR=48000; buf=bytearray()
    def gen():
        f=yield
        while True: buf.extend(f); f=yield
    cap=miniaudio.CaptureDevice(input_format=miniaudio.SampleFormat.SIGNED16, nchannels=1, sample_rate=CAP_SR, device_id=dev["id"])
    g=gen(); next(g)
    print(f"Recording from '{dev['name']}' @ {CAP_SR} Hz... press Enter to stop.")
    cap.start(g); input(); cap.stop()
    x=np.frombuffer(bytes(buf),dtype=np.int16).astype(np.float32)/32768.0
    return _resample(x,CAP_SR,SR)
def mix(sp,nz,snr,peak):
    if len(nz)<len(sp): nz=np.tile(nz,int(np.ceil(len(sp)/len(nz))))
    nz=nz[:len(sp)]; rs=np.sqrt(np.mean(sp**2)); rn=np.sqrt(np.mean(nz**2))
    if rs==0 or rn==0: sys.exit("silent input (rms=0)")
    g=(rs/rn)/(10**(snr/20)); m=sp+g*nz
    return _norm(m,peak),g
def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("--snr",type=float,default=0.0); ap.add_argument("--peak",type=float,default=0.95)
    ap.add_argument("--device",type=int,default=None,help="capture device index (see --list)")
    ap.add_argument("--list",action="store_true"); ap.add_argument("--out",default="mixed.wav"); ap.add_argument("--speech-out",default="speech.wav")
    a=ap.parse_args()
    if a.list: list_devices(); return
    try: sp=record(pick_device(a.device))
    except Exception as e: sys.exit(f"capture failed ({e}). pip install --user --break-system-packages miniaudio numpy")
    rms=float(np.sqrt(np.mean(sp**2))) if len(sp) else 0.0
    write_wav_mono(a.speech_out,_norm(sp,a.peak))
    bed=read_wav_mono_bytes(gzip.decompress(base64.b64decode(BED_GZ_B64)))
    m,g=mix(sp,bed,a.snr,a.peak); write_wav_mono(a.out,m)
    print(f"speech {a.speech_out} ({len(sp)/SR:.1f}s, in-rms {rms:.4f}) | mixed {a.out} @ {a.snr:+.0f}dB peak {a.peak} (gain {g:.3f})")
    if rms<0.005: print("  note: very low input level -- raise mic gain (pavucontrol / alsamixer) for a cleaner result.")
if __name__=="__main__": main()
